1	package net.officefloor.hq.app.setting;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.ArrayList;
7	import java.util.Arrays;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Objects;
12	import java.util.Optional;
13	import java.util.TreeMap;
14	import net.officefloor.hq.app.Audit;
15	import net.officefloor.hq.app.history.History;
16	import net.officefloor.hq.app.sheet.Sheet;
17	import net.officefloor.hq.app.sheet.SheetRepository;
18	import net.officefloor.hq.app.sheet.SheetService;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	/** A sheet's settings: the role each user name has on it, and its clerk limit, its floor, its cap, its proof threshold, its terms
23	 *  (and any grade's own terms) and its late percent, its policy date, its period numbering from and its grace days. The
24	 *  settings that carry a figure are dated: each value recorded is in force from its from-date. A claim's
25	 *  floor, late percent, terms and proof threshold are those in force on its date; the clerk limit and the cap those in
26	 *  force on the sheet's today. */
27	@Service
28	public class SettingService {
29	
30	    /** The key prefix of a grade's own terms: terms-A, terms-B, terms-C. */
31	    private static final String GRADE_TERMS = "terms-";
32	
33	    private final SheetService sheets;
34	    private final SheetRepository sheetRepository;
35	    private final SheetRoleRepository roles;
36	    private final SettingValueRepository values;
37	    private final SheetPermissionRepository permissions;
38	    private final DelegationRepository delegations;
39	    private final History history;
40	    private final Audit audit;
41	
42	    public SettingService(SheetService sheets, SheetRepository sheetRepository, SheetRoleRepository roles,
43	            SettingValueRepository values, SheetPermissionRepository permissions, DelegationRepository delegations,
44	            History history, Audit audit) {
45	        this.history = history;
46	        this.sheets = sheets;
47	        this.sheetRepository = sheetRepository;
48	        this.roles = roles;
49	        this.values = values;
50	        this.permissions = permissions;
51	        this.delegations = delegations;
52	        this.audit = audit;
53	    }
54	
55	    /** The keys the values of the settings that are not dated are kept under (see {@link History#settings}). */
56	    private static final String ROLE = "role:";
57	    private static final String PERMISSION = "perm:";
58	    private static final String NUMBERING_FROM = "period-numbering-from";
59	    private static final String GRACE_DAYS = "grace-days";
60	
61	    /** The sheet's settings as they stood at the end of a past day: each value as it stood set then,
62	     *  the day standing in for the sheet's today in those in force on a date. */
63	    public record AsOfView(Map<String, String> roles, Map<String, String> permissions, LocalDate periodNumberingFrom,
64	            Integer graceDays, List<Delegation> delegations, BigDecimal clerkLimit, BigDecimal floor, BigDecimal cap,
65	            int terms, BigDecimal latePct, LocalDate policyDate, Map<String, Integer> gradeTerms,
66	            Map<String, List<SettingValue>> dated) {
67	    }
68	
69	    /** The sheet's settings as they stood at the end of a day. A setting that is not dated whose
70	     *  value was never kept stands as it is now; one kept only after the day was not set then. */
71	    public AsOfView asOf(String sheetId, LocalDate day) {
72	        Map<String, String> then = history.settings(sheetId, day);
73	        List<String> kept = history.settingsKept(sheetId);
74	        Map<String, String> byUser = new TreeMap<>();
75	        roles(sheetId).forEach(r -> byUser.put(r.getUser(), r.getRole().label()));
76	        Map<String, String> byAction = permissions(sheetId);
77	        for (String key : kept) {
78	            String value = then.get(key);
79	            if (key.startsWith(ROLE)) {
80	                String user = key.substring(ROLE.length());
81	                if (value == null) {
82	                    byUser.remove(user);
83	                } else {
84	                    byUser.put(user, value);
85	                }
86	            } else if (key.startsWith(PERMISSION)) {
87	                byAction.put(key.substring(PERMISSION.length()), value != null ? value : "");
88	            }
89	        }
90	        String numbering = kept.contains(NUMBERING_FROM) ? then.get(NUMBERING_FROM)
91	                : Objects.toString(periodNumberingFrom(sheetId), null);
92	        String grace = kept.contains(GRACE_DAYS) ? then.get(GRACE_DAYS) : Objects.toString(graceDays(sheetId), null);
93	        Map<String, List<SettingValue>> dated = history.dated(sheetId, day);
94	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
95	        dated.forEach((key, recorded) -> {
96	            if (key.startsWith(GRADE_TERMS)) {
97	                recorded.stream().filter(v -> !v.getFrom().isAfter(day)).reduce((a, b) -> b)
98	                        .ifPresent(v -> gradeTerms.put(key.substring(GRADE_TERMS.length()), v.getValue().intValue()));
99	            }
100	        });
101	        return new AsOfView(byUser, byAction, numbering != null ? LocalDate.parse(numbering) : null,
102	                grace != null ? Integer.valueOf(grace) : null,
103	                delegations(sheetId).stream().filter(d -> d.madeAsOf(day)).toList(),
104	                inForce(sheetId, "clerk-limit", day, day).map(SettingValue::getValue).orElse(null),
105	                floor(sheetId, day, day),
106	                inForce(sheetId, "cap", day, day).map(SettingValue::getValue).orElse(null),
107	                inForce(sheetId, "terms", day, day).map(v -> v.getValue().intValue()).orElse(START_TERMS),
108	                latePct(sheetId, day, day), history.policyDate(sheetId, day), gradeTerms, dated);
109	    }
110	
111	    /** The roles assigned on the sheet, by user name. */
112	    public List<SheetRole> roles(String sheetId) {
113	        return roles.findBySheetIdOrderByUserAsc(sheetId);
114	    }
115	
116	    /** The user's role on the sheet as it acts: a steward while a delegation to it is in force on the
117	     *  sheet's today, else its own role. */
118	    public Role roleOf(String sheetId, String user) {
119	        return delegatedBy(sheetId, user).isPresent() ? Role.STEWARD : ownRole(sheetId, user);
120	    }
121	
122	    /** The role assigned the user on the sheet: clerk unless assigned another. */
123	    public Role ownRole(String sheetId, String user) {
124	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
125	    }
126	
127	    /** The steward who delegated the steward role to the user by a delegation in force on the sheet's
128	     *  today (the latest made); empty when none is. */
129	    public Optional<String> delegatedBy(String sheetId, String user) {
130	        List<Delegation> made = delegations.findBySheetIdAndUserOrderByIdDesc(sheetId, user);
131	        if (made.isEmpty()) {
132	            return Optional.empty();
133	        }
134	        LocalDate today = sheets.today(sheetId);
135	        return made.stream().filter(d -> d.covers(today)).map(Delegation::getBy).findFirst();
136	    }
137	
138	    /** The delegations made on the sheet, in the order made. */
139	    public List<Delegation> delegations(String sheetId) {
140	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
141	    }
142	
143	    /** Delegate the steward role to a user from a from-date (null for the sheet's today) to a to-date
144	     *  (null for the from-date), inclusive; anyone but a steward by their own role, or a to-date before
145	     *  the from-date, is refused. */
146	    @Transactional
147	    public Delegation delegate(String sheetId, String by, String user, LocalDate from, LocalDate to) {
148	        sheets.lock(sheetId);
149	        if (ownRole(sheetId, by) != Role.STEWARD) {
150	            throw new DelegationRefusedException("Only a steward can delegate the steward role");
151	        }
152	        LocalDate start = from != null ? from : sheets.today(sheetId);
153	        LocalDate end = to != null ? to : start;
154	        if (end.isBefore(start)) {
155	            throw new DelegationRefusedException("The to-date is before the from-date");
156	        }
157	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, user, start, end, by, sheets.today(sheetId)));
158	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + by + " user=" + user + " from=" + start
159	                + " to=" + end);
160	        return saved;
161	    }
162	
163	    /** Whether the user is a viewer on the sheet: one who can change nothing. */
164	    public boolean isViewer(String sheetId, String user) {
165	        return roleOf(sheetId, user) == Role.VIEWER;
166	    }
167	
168	    /** The sheet's permission matrix as set, by action label, every action listed: its roles comma
169	     *  separated, blank when it keeps the standing rule. */
170	    public Map<String, String> permissions(String sheetId) {
171	        Map<String, String> byAction = new LinkedHashMap<>();
172	        for (Permission action : Permission.values()) {
173	            byAction.put(action.label(), "");
174	        }
175	        permissions.findBySheetId(sheetId).forEach(p -> byAction.put(p.getAction(), p.getRoles()));
176	        return byAction;
177	    }
178	
179	    /** Whether the user's role may take the action on the sheet: by the roles the matrix lists for it,
180	     *  else by the standing rule. */
181	    public boolean allows(String sheetId, String user, Permission action) {
182	        Role role = roleOf(sheetId, user);
183	        if (role == Role.VIEWER) {
184	            return false;
185	        }
186	        return permissions.findBySheetIdAndAction(sheetId, action.label())
187	                .map(p -> Arrays.stream(p.getRoles().split(",")).anyMatch(r -> r.equals(role.label())))
188	                .orElseGet(() -> action.standing().contains(role));
189	    }
190	
191	    /** Refuse the action unless the user's role may take it on the sheet. */
192	    public void refuseUnless(String sheetId, String user, Permission action) {
193	        if (!allows(sheetId, user, action)) {
194	            throw new PermissionRefusedException(user, action);
195	        }
196	    }
197	
198	    /** Set the roles that may take an action on the sheet; none keeps the standing rule. */
199	    @Transactional
200	    public void setPermission(String sheetId, String by, Permission action, List<Role> allowed) {
201	        sheets.lock(sheetId);
202	        String value = String.join(",", allowed.stream().map(Role::label).toList());
203	        Optional<SheetPermission> existing = permissions.findBySheetIdAndAction(sheetId, action.label());
204	        if (value.isEmpty()) {
205	            existing.ifPresent(p -> {
206	                permissions.delete(p);
207	                permissions.flush();
208	            });
209	        } else {
210	            SheetPermission saved = existing.orElseGet(() -> new SheetPermission(sheetId, action.label(), value));
211	            saved.setRoles(value);
212	            permissions.saveAndFlush(saved);
213	        }
214	        history.settingSet(sheetId, PERMISSION + action.label(), value.isEmpty() ? null : value);
215	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=perm-" + action.label()
216	                + " value=" + value);
217	    }
218	
219	    /** The floor a sheet starts with: in force before the first from-date recorded for it. */
220	    public static final BigDecimal START_FLOOR = new BigDecimal("1.00");
221	
222	    /** The late percent a sheet starts with. */
223	    public static final BigDecimal START_LATE_PCT = new BigDecimal("0.00");
224	
225	    /** The terms a sheet starts with, in days. */
226	    public static final int START_TERMS = 14;
227	
228	    /** The values recorded for the sheet's dated settings, by key, each list by from-date. */
229	    public Map<String, List<SettingValue>> dated(String sheetId) {
230	        Map<String, List<SettingValue>> byKey = new TreeMap<>();
231	        values.findBySheetIdOrderByKeyAscFromAsc(sheetId)
232	                .forEach(v -> byKey.computeIfAbsent(v.getKey(), k -> new ArrayList<>()).add(v));
233	        return byKey;
234	    }
235	
236	    /** The value recorded for a dated setting that is in force on a date: the one with the latest
237	     *  from-date on or before it; empty before every from-date (the sheet's starting value applies). */
238	    private Optional<SettingValue> inForce(String sheetId, String key, LocalDate on) {
239	        return values.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(sheetId, key, on);
240	    }
241	
242	    /** A dated setting's value in force on a date as the values stood at the end of a day (null: as
243	     *  they stand now). */
244	    private Optional<SettingValue> inForce(String sheetId, String key, LocalDate on, LocalDate asOf) {
245	        return asOf == null ? inForce(sheetId, key, on) : history.setting(sheetId, key, on, asOf);
246	    }
247	
248	    /** The sheet's clerk limit in force on its today; null when there is none. */
249	    public BigDecimal clerkLimit(String sheetId) {
250	        return inForce(sheetId, "clerk-limit", sheets.today(sheetId)).map(SettingValue::getValue).orElse(null);
251	    }
252	
253	    /** The sheet's floor in force on a date: the least the live due of a claim of that date can be. */
254	    public BigDecimal floor(String sheetId, LocalDate on) {
255	        return floor(sheetId, on, null);
256	    }
257	
258	    /** The sheet's floor in force on a date as it stood at the end of a day (null: as it stands now). */
259	    public BigDecimal floor(String sheetId, LocalDate on, LocalDate asOf) {
260	        return inForce(sheetId, "floor", on, asOf).map(SettingValue::getValue).orElse(START_FLOOR);
261	    }
262	
263	    /** The sheet's cap in force on its today: the most a person's due-total can be; null when there is none. */
264	    public BigDecimal cap(String sheetId) {
265	        return inForce(sheetId, "cap", sheets.today(sheetId)).map(SettingValue::getValue).orElse(null);
266	    }
267	
268	    /** The sheet's proof threshold in force on a date: a claim of that date whose due is above it cannot
269	     *  be settled or approved while it has no proofs; null when there is none. */
270	    public BigDecimal proofThreshold(String sheetId, LocalDate on) {
271	        return inForce(sheetId, "proof-threshold", on).map(SettingValue::getValue).orElse(null);
272	    }
273	
274	    /** The sheet's note threshold in force on a date: a claim of that date whose due is above it cannot
275	     *  be opened while its note is empty; null when there is none. */
276	    public BigDecimal noteThreshold(String sheetId, LocalDate on) {
277	        return inForce(sheetId, "note-threshold", on).map(SettingValue::getValue).orElse(null);
278	    }
279	
280	    /** A person's due-total held to the sheet's cap; a due-total of none (n/a) is not capped. */
281	    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
282	        return capped(sheetId, dueTotal, null);
283	    }
284	
285	    /** A person's due-total held to the cap in force at the end of a day, as it stood then, the day
286	     *  standing in for the sheet's today (null: the cap in force on the sheet's today now). */
287	    public BigDecimal capped(String sheetId, BigDecimal dueTotal, LocalDate asOf) {
288	        BigDecimal cap = asOf == null ? cap(sheetId)
289	                : inForce(sheetId, "cap", asOf, asOf).map(SettingValue::getValue).orElse(null);
290	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
291	    }
292	
293	    /** The sheet's terms in days in force on a date: a claim of that date is due by its date plus them. */
294	    public int terms(String sheetId, LocalDate on) {
295	        return inForce(sheetId, "terms", on).map(v -> v.getValue().intValue()).orElse(START_TERMS);
296	    }
297	
298	    /** The grades' own terms in force on a date, by grade; a grade not listed takes the sheet's terms. */
299	    public Map<String, Integer> gradeTerms(String sheetId, LocalDate on) {
300	        Map<String, Integer> byGrade = new LinkedHashMap<>();
301	        dated(sheetId).forEach((key, recorded) -> {
302	            if (!key.startsWith(GRADE_TERMS)) {
303	                return;
304	            }
305	            recorded.stream().filter(v -> !v.getFrom().isAfter(on)).reduce((a, b) -> b)
306	                    .ifPresent(v -> byGrade.put(key.substring(GRADE_TERMS.length()), v.getValue().intValue()));
307	        });
308	        return byGrade;
309	    }
310	
311	    /** The terms in days a claim of the grade dated on a date takes: the grade's own in force then,
312	     *  else the sheet's. */
313	    public int termsFor(String sheetId, String grade, LocalDate on) {
314	        if (grade == null) {
315	            return terms(sheetId, on);
316	        }
317	        return inForce(sheetId, GRADE_TERMS + grade, on).map(v -> v.getValue().intValue())
318	                .orElseGet(() -> terms(sheetId, on));
319	    }
320	
321	    /** The sheet's late percent in force on a date: an overdue claim of that date's due gains it of its
322	     *  figure for every full 30 days it is overdue. */
323	    public BigDecimal latePct(String sheetId, LocalDate on) {
324	        return latePct(sheetId, on, null);
325	    }
326	
327	    /** The sheet's late percent in force on a date as it stood at the end of a day (null: as it
328	     *  stands now). */
329	    public BigDecimal latePct(String sheetId, LocalDate on, LocalDate asOf) {
330	        return inForce(sheetId, "late-pct", on, asOf).map(SettingValue::getValue).orElse(START_LATE_PCT);
331	    }
