338	    /** The sheet's policy date in force: as set, else the sheet's today. */
339	    public LocalDate policyDate(String sheetId) {
340	        LocalDate set = policyDateSet(sheetId);
341	        return set != null ? set : sheets.today(sheetId);
342	    }
343	
344	    /** The sheet's period numbering from; null when it is blank (off). */
345	    public LocalDate periodNumberingFrom(String sheetId) {
346	        return sheets.load(sheetId).getPeriodNumberingFrom();
347	    }
348	
349	    /** The sheet's grace days; null when they are blank (off). */
350	    public Integer graceDays(String sheetId) {
351	        return sheets.load(sheetId).getGraceDays();
352	    }
353	
354	    /** How a claim dated on the given date rounds: half up before the policy date, half to even on or
355	     *  after it. */
356	    public RoundingMode roundingOn(String sheetId, LocalDate date) {
357	        return roundingOn(sheetId, date, null);
358	    }
359	
360	    /** How a claim dated on the given date rounds by the policy date as it stood set at the end of a
361	     *  day, the day standing in for the sheet's today (null: as it stands now). */
362	    public RoundingMode roundingOn(String sheetId, LocalDate date, LocalDate asOf) {
363	        LocalDate policy = asOf == null ? policyDate(sheetId) : history.policyDate(sheetId, asOf);
364	        if (policy == null) {
365	            policy = asOf;
366	        }
367	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
368	    }
369	
370	    /** Assign a user name a role on the sheet. */
371	    @Transactional
372	    public SheetRole setRole(String sheetId, String by, String user, Role role) {
373	        sheets.lock(sheetId);
374	        SheetRole saved = roles.findBySheetIdAndUser(sheetId, user)
375	                .map(existing -> {
376	                    existing.setRole(role);
377	                    return existing;
378	                })
379	                .orElseGet(() -> new SheetRole(sheetId, user, role));
380	        saved = roles.saveAndFlush(saved);
381	        history.settingSet(sheetId, ROLE + user, role.label());
382	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role.label());
383	        return saved;
384	    }
385	
386	    /** Record the sheet's clerk limit from a date (null for the sheet's today); a null limit records none. */
387	    @Transactional
388	    public SettingValue setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
389	        return record(sheetId, by, "clerk-limit", limit != null ? limit.setScale(2, RoundingMode.UNNECESSARY) : null, from);
390	    }
391	
392	    /** Record the sheet's floor from a date (null for the sheet's today). */
393	    @Transactional
394	    public SettingValue setFloor(String sheetId, String by, BigDecimal floor, LocalDate from) {
395	        return record(sheetId, by, "floor", floor.setScale(2, RoundingMode.UNNECESSARY), from);
396	    }
397	
398	    /** Record the sheet's cap from a date (null for the sheet's today); a null cap records none. */
399	    @Transactional
400	    public SettingValue setCap(String sheetId, String by, BigDecimal cap, LocalDate from) {
401	        return record(sheetId, by, "cap", cap != null ? cap.setScale(2, RoundingMode.UNNECESSARY) : null, from);
402	    }
403	
404	    /** Record the sheet's proof threshold from a date (null for the sheet's today); a null threshold
405	     *  records none. */
406	    @Transactional
407	    public SettingValue setProofThreshold(String sheetId, String by, BigDecimal threshold, LocalDate from) {
408	        return record(sheetId, by, "proof-threshold",
409	                threshold != null ? threshold.setScale(2, RoundingMode.UNNECESSARY) : null, from);
410	    }
411	
412	    /** Record the sheet's note threshold from a date (null for the sheet's today); a null threshold
413	     *  records none. */
414	    @Transactional
415	    public SettingValue setNoteThreshold(String sheetId, String by, BigDecimal threshold, LocalDate from) {
416	        return record(sheetId, by, "note-threshold",
417	                threshold != null ? threshold.setScale(2, RoundingMode.UNNECESSARY) : null, from);
418	    }
419	
420	    /** Record the sheet's terms from a date (null for the sheet's today). */
421	    @Transactional
422	    public SettingValue setTerms(String sheetId, String by, int terms, LocalDate from) {
423	        return record(sheetId, by, "terms", BigDecimal.valueOf(terms), from);
424	    }
425	
426	    /** Record a grade's own terms on the sheet from a date (null for the sheet's today). */
427	    @Transactional
428	    public SettingValue setGradeTerms(String sheetId, String by, String grade, int terms, LocalDate from) {
429	        return record(sheetId, by, GRADE_TERMS + grade, BigDecimal.valueOf(terms), from);
430	    }
431	
432	    /** Record the sheet's late percent from a date (null for the sheet's today). */
433	    @Transactional
434	    public SettingValue setLatePct(String sheetId, String by, BigDecimal latePct, LocalDate from) {
435	        return record(sheetId, by, "late-pct", latePct.setScale(2, RoundingMode.UNNECESSARY), from);
436	    }
437	
438	    /** Record a dated setting's value from a date, the sheet's today when none is given, keeping the
439	     *  values already recorded; one already recorded from that date is replaced. */
440	    private SettingValue record(String sheetId, String by, String key, BigDecimal value, LocalDate from) {
441	        sheets.lock(sheetId);
442	        LocalDate on = from != null ? from : sheets.today(sheetId);
443	        SettingValue saved = values.findBySheetIdAndKeyAndFrom(sheetId, key, on)
444	                .map(existing -> {
445	                    existing.setValue(value);
446	                    return existing;
447	                })
448	                .orElseGet(() -> new SettingValue(sheetId, key, on, value));
449	        saved = values.saveAndFlush(saved);
450	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=" + key + " value="
451	                + (value != null ? (key.startsWith("terms") ? String.valueOf(value.intValue()) : value.toPlainString()) : "")
452	                + (from != null ? " from=" + from : ""));
453	        return saved;
454	    }
455	
