    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    /** Add a claim for a person; a missing date takes the sheet's today. One added while the period
     *  its date falls in is soft-closed is a late entry. Its due-by is fixed now: its
     *  date plus the person's own terms, else the terms in force on that date for the person's grade then. A negative amount is a
     *  correction and must name a SETTLED claim of the person it corrects. */
    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Person person = person(sheetId, personId);
        corrects = numberOf(corrects);
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        LocalDate dueBy = on.plusDays(termsFor(sheetId, person, on));
        Claim claim = new Claim(sheetId, personId, scaled(amount), on, dueBy, noteOf(note), corrects);
        boolean late = periods.softClosedOn(sheetId, on);
        if (late) {
            claim.markLateEntry();
        }
        Claim added = claims.saveAndFlush(claim);
        log(sheetId, user, person, added);
        record("CLAIM_ADDED", sheetId, user, person, added);
        if (late) {
            record("LATE_ENTRY", sheetId, user, person, added);
        }
        return added;
    }

    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
    @Transactional
    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
            String note, String corrects) {
        Person person = person(sheetId, personId);
        corrects = numberOf(corrects);
        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotEditableException(claim.getStatus());
        }
        if (claim.lockedAgainst(user)) {
            throw new ClaimLockedException(claim.getLockedBy());
        }
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        claim.setAmount(scaled(amount));
        claim.setCorrects(corrects);
        claim.setDate(on);
        claim.setNote(noteOf(note));
        claim.setLockedBy(null);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_EDITED", sheetId, user, person, saved);
        return saved;
    }

    /** Open a claim's editor: lock the claim to the user until they save or cancel it, or the
     *  sheet's today changes. A claim that is not a DRAFT, is dated in a closed period, or is locked
    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claims,
            RollupService rollups) {
        this.people = people;
        this.personService = personService;
        this.claims = claims;
        this.rollups = rollups;
    }

    /** Add a claim of the amount, dated the sheet's today with an empty note, for the named person. */
    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = rollups.track(sheetId, user, () -> people.findByName(sheetId, trimmed)
                .orElseGet(() -> personService.add(sheetId, user, trimmed, GRADE)));
        Claim claim = rollups.track(sheetId, user, () -> claims.add(sheetId, user, person.getId(), amount, null, "", null));
        return new Added(person, claim);
    }
}
package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim per pasted line of name,amount,date,note for a person named on the sheet.
 *  Every line is checked first; the whole paste is one change, so one refused line adds nothing. */
@Service
public class PasteService {

    /** The most a claim's note holds, as on the claim form. */
    private static final int NOTE_MAX = 2000;

    /** A pasted line, read: the person it names and the claim's figures (a null date: the sheet's today). */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note) {
    }

    private final PersonRepository people;
    private final ClaimService claims;
    private final RollupService rollups;

    public PasteService(PersonRepository people, ClaimService claims, RollupService rollups) {
        this.people = people;
        this.claims = claims;
        this.rollups = rollups;
    }

    /** Add the pasted claims in the order of their lines; blank lines are skipped. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        int at = 0;
        for (String raw : text.split("\\r?\\n")) {
            at++;
            if (!raw.isBlank()) {
                lines.add(read(sheetId, at, raw));
            }
        }
        if (lines.isEmpty()) {
            throw new PasteRefusedException("Nothing to add");
        }
        return rollups.track(sheetId, user, () -> lines.stream()
                .map(l -> claims.add(sheetId, user, l.person().getId(), l.amount(), l.date(), l.note(), null))
                .toList());
    }

    /** One line as the claim form reads it: an amount of 0.00 or more with up to two decimals, a
     *  date (blank: the sheet's today) and a note (absent: empty) that may hold commas. */
    private Line read(String sheetId, int at, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 3) {
            throw new PasteRefusedException("Line " + at + " needs name,amount,date");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null : people.findByName(sheetId, name).orElse(null);
        if (person == null) {
            throw new PasteRefusedException("Line " + at + ": no person " + name + " on the sheet");
        }
        BigDecimal amount;
        try {
            amount = new BigDecimal(fields[1].trim());
        } catch (NumberFormatException e) {
            throw new PasteRefusedException("Line " + at + ": the amount is not a number");
        }
        if (amount.signum() < 0 || amount.scale() > 2 || amount.precision() - amount.scale() > 10) {
            throw new PasteRefusedException("Line " + at + ": the amount must be 0.00 or more, with up to two decimals");
        }
        LocalDate date;
        try {
            date = fields[2].isBlank() ? null : LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw new PasteRefusedException("Line " + at + ": the date is not a date");
        }
        String note = fields.length > 3 ? fields[3].trim() : "";
        if (note.length() > NOTE_MAX) {
            throw new PasteRefusedException("Line " + at + ": the note is too long");
        }
        return new Line(person, amount, date, note);
    }
}

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String method = request.getMethod();
        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!paths.match(PATTERN, path) || LET_THROUGH.stream().anyMatch(p -> paths.match(p, path))) {
            return true;
        }
        String header = request.getHeader(SignedInUser.HEADER);
        if (header == null || header.isBlank()) {
            return true;
        }
        Map<String, String> vars = paths.extractUriTemplateVariables(PATTERN, path);
        String sheetId = URLDecoder.decode(vars.get("sheetId"), StandardCharsets.UTF_8).trim();
        if (settings.isViewer(sheetId, SignedInUser.decode(header))) {
            response.setStatus(HttpStatus.FORBIDDEN.value());
            return false;
        }

