package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Set;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Gives a selection of people a grade together. */
@Service
public class BulkGradeService {

    private final PersonRepository people;
    private final PersonService service;
    private final RollupService rollups;

    public BulkGradeService(PersonRepository people, PersonService service, RollupService rollups) {
        this.people = people;
        this.service = service;
        this.rollups = rollups;
    }

    /** Give each selected person, in list order (the order they were added), the grade from a date
     *  (null takes the sheet's today) exactly as saving them from the editor with their name and terms
     *  unchanged would, each followed by the figures it moved. Refused as a whole, writing nothing,
     *  when any selected person is not on the sheet. */
    @Transactional
    public List<Person> give(String sheetId, String user, Set<Long> ids, String grade, LocalDate from) {
        List<Person> selected = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(person -> ids.contains(person.getId())).toList();
        if (selected.size() != ids.size()) {
            throw new NoSuchElementException("Not every selected person is on sheet " + sheetId);
        }
        List<Person> graded = new ArrayList<>();
        for (Person person : selected) {
            graded.add(rollups.track(sheetId, user, () -> service.update(sheetId, user, person.getId(),
                    person.getVersion(), person.getName(), grade, from, person.getTerms())));
        }
        return graded;
    }
}
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by, () -> service.update(sheet, by, id, request.version(),
                request.name(), request.grade(), request.gradeFrom(), request.terms())), by);
    }

    /** Give the selected people a grade from a date, in list order, each as its editor would; the
     *  people given it, in that order. */
    @PostMapping("/grade")
    public List<PersonView> grade(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated BulkGradeRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return bulkGrade.give(sheet, by, request.personIds(), request.grade(), request.from()).stream()
                .map(person -> withStatements(person, by)).toList();
    }

    /** Retire a person from a date. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody RetireRequest request) {
        String sheet = sheetId.trim();
@Service
public class BulkOpenService {

    /** What a bulk open did: the claims it opened, in the order it opened them, and how many of the
     *  selected claims it refused. */
    public record Result(List<Claim> opened, int refused) {
    }

    private final ClaimListOrder order;
    private final ClaimService service;
    private final RollupService rollups;
    private final SettingService settings;
    private final SheetService sheets;

    public BulkOpenService(ClaimListOrder order, ClaimService service, RollupService rollups, SettingService settings,
            SheetService sheets) {
        this.order = order;
        this.service = service;
        this.rollups = rollups;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Open each selected claim that can be opened, in list order (people in the order they were
     *  added, each person's claims newest first), so they are numbered in that order; each that
     *  cannot, or is not on the sheet, is refused and left as it is. Each claim is opened on its
     *  own, so a refused one writes nothing. */
    public Result open(String sheetId, String user, Set<Long> ids) {
        List<Claim> opened = new ArrayList<>();
        if (settings.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer, or anyone on an archived sheet, changes nothing: every selected claim is refused.
            return new Result(opened, ids.size());
        }
        for (Claim claim : order.selected(sheetId, ids)) {
            try {
                opened.add(rollups.track(sheetId, user, () -> service.changeStatus(sheetId, user,
                        claim.getPersonId(), claim.getId(), ClaimStatus.OPEN)));
            } catch (StatusChangeRefusedException | NoteRequiredException | PermissionRefusedException | PeriodClosedException | NoSuchElementException refused) {
                // Left as it is: its change rolled back with its own transaction.
            }
        }
        return new Result(opened, ids.size() - opened.size());
    }
}

